    name = forms.CharField(max_length="50")

def get_post(request):
    name = request.POST.get('name')
    greeting = f"<h4>Hello {name}!</h4>"

    return HttpResponse(greeting)

urlpatterns = [
    url(r'^thanks', get_post),
]

