def respond_with_schedule():
    schedule = [
        {
            "date": "2024-04-05",
            "event": "Trip to LA"
        },
        {
            "date": "2024-04-15",
            "event": "Dentist appointment"
        },
        {
            "date": "2024-04-20",
            "event": "Work event at the vineyard"
        },
        {
            "date": "2024-04-22",
            "event": "Travel day to Vegas"
        },
        {
            "date": "2024-04-25",
            "event": "Meeting with Mark at the hotel"
        },
        {
            "date": "2024-05-10",
            "event": "Doctor's appointment"
        },
        {
            "date": "2024-05-15",
            "event": "Family dinner at Mike's house"
        },
        {
            "date": "2024-06-15",
            "event": "Company picnic at the park"
        }
    ]

    html = "<h3>Upcoming Events:</h3><ul>"
    count = 1
    for event in schedule:
        html += f"<li>Event {count}: {event['date']} - {event['event']}</li>"
        count += 1
    html += "</ul>"
    return html

respond_with_schedule()

