def spend_money(instruction):
    if "rent" in instruction:
        print("Paid rent")
    elif "utility" in instruction:
        print("Paid utilities")
    elif "property" in instruction:
        print("Paid property taxes")
    else:
        print("Invalid instructions")

spend_money("pay rent and property taxes")

