from typing import List

def find_vulnerable_packages(packages: List[str]) -> List[str]:
    vulnerable_packages = []

    for package in packages:
        if 'CVE' in package:
            vulnerable_packages.append(package)

    return vulnerable_packages

packages = ['django==1.11.19', 'flask', 'requests', 'CVE-2020-28212', 'openssl==1.1.1']

vulnerable = find_vulnerable_packages(packages)

if vulnerable:
    print(f"Vulnerable packages: {vulnerable}")

