from pathlib import Path

def find_files(path):
    if not path.exists() or not path.is_dir():
        return []
    files = []
    for p in path.glob("."):
        if p.is_file():
            files.append(p)
        find_files(p)
    return files

files = find_files(Path("/my/project"))

with open("/tmp/listing", "w") as f:
    for file in files:
        f.write(file.name + "\n")

